\subsection{Toy study: full specification}
\label{app:toy}

\emph{Applied-update projection is the only constraint that is both exact and stable.} The controlled setup below isolates where the projection is applied. All schemes learn the toy task, but only projecting the optimizer's applied update eliminates protected-subspace leakage without substantially changing the held-out capability.

\paragraph{Model, optimizer, targets.} Qwen2.5-0.5B, fine-tuned with plain AdamW at learning
rate $1{\times}10^{-4}$ and weight decay $0$ (unless stated). Each scheme's projection is applied to
the standard target linears---attention $q,k,v,o$ and MLP $gate,up,down$.

\paragraph{Task ($8$ fixed examples).} Next-token cross-entropy on the completion tokens only (prompt
tokens masked), on eight short prompt$\to$completion pairs: \texttt{("The capital of France is",
" Paris.")}, \texttt{("2 plus 3 equals", " 5.")}, \texttt{("The opposite of hot is", " cold.")},
\texttt{("Water is made of hydrogen and", " oxygen.")}, \texttt{("The first month of the year is",
" January.")}, \texttt{("A group of wolves is called a", " pack.")}, \texttt{("The chemical symbol for
gold is", " Au.")}, \texttt{("Seven times eight is", " 56.")}. The task is trivially learnable, so
every scheme drives task loss to ${\approx}0$; the discriminator is the forgetting on out of domain tasks.

\paragraph{Capability probe (held-out).} Mean per-token NLL on four generic sentences the model never
trains on; \textbf{Probe}$\Delta = \mathrm{NLL}_\text{after}-\mathrm{NLL}_\text{before}$ (base-model
probe NLL ${\approx}2.81$ nats/token). The probe sentences: \emph{``The history of the Roman Empire
spans over a thousand years of political change.''}; \emph{``Photosynthesis converts carbon dioxide
and water into glucose using sunlight.''}; \emph{``In distributed systems, consensus algorithms ensure
agreement despite failures.''}; \emph{``The novel explores themes of memory, loss, and the passage of
time.''}

\paragraph{The three enforcement schemes.} With projector $\Pi$ (Eq.~\ref{eq:proj}), Adam moments
$\hat m,\hat v$, and preconditioned raw step $\hat m/(\sqrt{\hat v}+\epsilon)$:
\begin{itemize}
\item \textbf{Project gradient}: $g\leftarrow\Pi(g)$; then $\hat m,\hat v \leftarrow \text{Adam}(g)$;
$W\leftarrow W-\text{lr}\cdot\hat m/(\sqrt{\hat v}+\epsilon)$. Here $\hat v$ sees only free-subspace
energy, and the applied step $D\,\Pi(\hat m)$ with $D=\mathrm{diag}(1/(\sqrt{\hat v}+\epsilon))$
re-enters the protected space because $D$ and $\Pi$ do not commute.
\item \textbf{Project the applied update}: $\hat m,\hat v\leftarrow\text{Adam}(g)$ on the \emph{full}
gradient; $W_\text{pre}\leftarrow W$; $W\leftarrow W-\text{lr}\cdot\hat m/(\sqrt{\hat v}+\epsilon)$;
$W\leftarrow W_\text{pre}+\Pi(W-W_\text{pre})$. The update is confined to the low singular value subspace because projection is last, and
the free step keeps the scale induced by the full gradient.
\item \textbf{Re-project cumulative change}: $g\leftarrow\Pi(g)$; take the Adam step; then set
$W\leftarrow W_\text{ref}+\Pi(W-W_\text{ref})$. Note that $W\leftarrow W_\text{ref}+\Pi(W-W_\text{ref})$
is equivalent to $W_t+\Pi(\delta_t)$, with $\delta_t$ the step just applied, since every previously
applied change already lies in the free subspace. The update lies in the correct subspace, but the step is based on
projected-gradient moments and is therefore mis-scaled.
\end{itemize}

\paragraph{The full procedure.} Algorithm~\ref{alg:sst} details SST's implementation, using the second
of these three schemes. A superscript $\ell$ indexes one constrained matrix, so $W_t^\ell$ is that
matrix at step $t$ and plays the role of $W_\text{pre}$ above. The optimizer itself is never
modified. It receives the full gradient, updates its moments, and proposes an ordinary step; SST
then replaces the part of that step which lands on a constrained matrix with its free-to-free block.
Parameters outside $\mathcal I$, such as embeddings and layer norms, are left to the optimizer.

\begin{algorithm}[htbp]
\caption{Subspace Tuning (SST). The optimizer runs untouched; SST edits only the update it
produces, keeping the free-to-free block of Eq.~\ref{eq:proj} and discarding the rest.}
\label{alg:sst}
\begin{algorithmic}[1]
\Require Constrained matrices $\mathcal I$ (attention $q,k,v,o$ and MLP gate, up, down) with
         pretrained weights $W^\ell$ of shape $d_\text{out}^\ell\times d_\text{in}^\ell$; rank
         fraction $r$, the share of singular directions held fixed; refresh interval $K$ in
         optimizer steps; optimizer $\mathcal O$ with state $s$; loss $\mathcal L$ with minibatches
         $\mathcal B_t$; step budget $T$.
\Statex
\Statex \textit{Setup: protect the leading singular subspace of all matrices in $\mathcal I$.}
\ForAll{$\ell\in\mathcal I$}
    \State $W_\text{ref}^\ell\gets W^\ell$
    \State $k_\ell\gets\left\lfloor r\min(d_\text{out}^\ell,d_\text{in}^\ell)\right\rfloor$
           \Comment{number of directions to protect}
    \State $U_k^\ell,V_k^\ell\gets$ top-$k_\ell$ left and right singular vectors of $W_\text{ref}^\ell$
    \State $Q_U^\ell\gets I-U_k^\ell(U_k^\ell)^\top,\quad
           Q_V^\ell\gets I-V_k^\ell(V_k^\ell)^\top$
           \Comment{the free complements}
\EndFor
\Statex
\Statex \textit{Training: take the ordinary step, then project the part that reaches the weights.}
\For{$t=0,\ldots,T-1$}
    \State $g_t\gets\nabla_W\mathcal L(W_t;\mathcal B_t)$
           \Comment{full gradient}
    \State $(\widetilde W_{t+1},s_{t+1})\gets\mathcal O(W_t,g_t,s_t)$
           \Comment{ordinary step}
    \State $W_{t+1}\gets\widetilde W_{t+1}$
    \ForAll{$\ell\in\mathcal I$}
        \State $\Delta W^\ell\gets\widetilde W_{t+1}^\ell-W_t^\ell$
               \Comment{the optimizer update}
        \State $W_{t+1}^\ell\gets W_t^\ell+
               Q_U^\ell\,\Delta W^\ell\,Q_V^\ell$
               \Comment{apply $\Pi(\Delta W^\ell)$ instead, Eq.~\ref{eq:proj}}
    \EndFor
    \If{$K<\infty$ and $(t+1)\bmod K=0$}
        \ForAll{$\ell\in\mathcal I$}
            \State $W_\text{ref}^\ell\gets W_{t+1}^\ell$
                   \Comment{re-compute projection with current weights}
            \State $U_k^\ell,V_k^\ell\gets$ top-$k_\ell$ singular vectors of $W_\text{ref}^\ell$
            \State $Q_U^\ell\gets I-U_k^\ell(U_k^\ell)^\top,\quad
                   Q_V^\ell\gets I-V_k^\ell(V_k^\ell)^\top$
        \EndFor
    \EndIf
\EndFor
\State \Return $W_T$
\end{algorithmic}
\end{algorithm}

