\section{Notation and Preliminaries}
All alphabets throughout the paper are finite, and we denote by $\log$ the logarithm in base 2.

Let $X$ be a random variable assuming values in an alphabet $\cX$. We denote by $P_X$ the probability distribution of $X$, that is, $P_X(x)=\mathbb{P}(X=x)$ for each $x\in \cX$. In addition, given a random variable $X$, we denote by
\begin{equation}\label{eq:Shannon_entropy_def}
    H(X)=-\sum_{x\in \cX} P_X(x)\log P_X(x)
\end{equation}
the Shannon entropy of $X$. Moreover, since $H(X)$ depends only on the distribution $P_X$, we also write $H(P_X)$ to denote the entropy of the distribution $P_X$.

Let $(X,Y)$ be a pair of random variables assuming values in the finite alphabet $\cX\times\cY$, with a joint probability distribution $P_{XY}$: 
\begin{align}
    P_{XY}(x,y)&=\mathbb{P}(X=x,Y=y),\quad\forall x\in \cX\text{ and } y\in\cY,
\end{align}
and marginal distributions
\begin{align}
     P_X(x)&=\sum_{y\in \cY} P_{XY}(x,y),\quad\forall x\in \cX,\\
    P_Y(y)&=\sum_{x\in \cX} P_{XY}(x,y),\quad\forall y\in \cY.
\end{align}
Without loss of generality, we assume that $P_X(x) > 0$ for all $x \in \cX$;
otherwise, we simply remove from $\cX$ the values with $P_X(x) = 0$. Then, for every $x\in \cX$,  the conditional distribution $P_{Y\mid X}(\cdot\mid x)$ of $Y$ given $X=x$ is
\begin{equation}
    P_{Y\mid X}(y\mid x)=\mathbb{P}(Y=y\mid X=x)=\frac{\mathbb{P}(X=x,Y=y)}{P_X(x)},\quad\forall y\in \cY.
\end{equation}
For each fixed $x$, $P_{Y\mid X}(\cdot \mid x)$ is a probability distribution
on $\cY$, and we denote by
\begin{equation}
    H(Y \mid X = x) = H\big(P_{Y\mid X}(\cdot \mid x)\big)
    = -\sum_{y\in\cY} P_{Y\mid X}(y \mid x) \log P_{Y\mid X}(y \mid x),
\end{equation}
the conditional entropy of $Y$ given $X=x$.

More generally, we recall that the conditional entropy of $Y$ given $X$ is defined as the average of $H(Y \mid X = x)$ with respect to $P_X$, that is,
\begin{equation}\label{eq:conditional_entropy}
    H(Y\mid X)=\E_{X}[H(Y\mid X)]=\sum_{x\in\cX} P_X(x)H(Y\mid X=x).
\end{equation}
Then, the mutual information between $X$ and $Y$ is defined as
\begin{equation}\label{eq:mutual_information_def}
    I(X;Y)=H(Y)-H(Y\mid X).
\end{equation}
The mutual information $I(X;Y)$ quantifies the reduction in the uncertainty about $Y$ given $X$. It is symmetric, i.e., $I(X;Y)=I(Y;X)$, and non-negative, $I(X;Y)\geq 0$.

Two random variables $X$ and $Y$, taking values in $\cX$ and $\cY$ respectively, are said to be independent if
\begin{equation}
    P_{XY}(x,y)=P_X(x)P_Y(y),\quad\forall x\in \cX\text{ and }y\in \cY.
\end{equation}
Similarly, let $(X,Y,T)$ be a triple of random variables having joint distribution $P_{XYT}$ on $\cX\times \cY\times \cT$. The random variables $Y$ and $T$ are said to be conditionally independent given $X$ if
\begin{equation}
    P_{YT\mid X}(y,t\mid x)=P_{Y\mid X}(y\mid x)P_{T\mid X}(t\mid x),\quad\forall x\in\cX, y\in \cY\text{ and } t\in \cT
\end{equation}
In other words, $Y$ and $T$ are independent under the conditional
distribution $P_{YT\mid X}(\cdot,\cdot \mid x)$, for every $x \in \cX$.

Let $P$ and $Q$ be two probability distributions on a finite set $S$, and let $\supp(P)=\{s\in S:P(s)>0\}$ and $\supp(Q)=\{s\in S:Q(s)>0\}$ denote the support of $P$ and $Q$, respectively. If $\supp(P)\subseteq \supp(Q)$, the Kullback-Leibler divergence $D(P\|Q)$ of $P$ from $Q$ is defined as 
\begin{equation}\label{eq:KL_def}
    D(P\| Q)=\sum_{s\in \supp(P)} P(s)\log \frac{P(s)}{Q(s)}.
\end{equation}
We assume that $0\log 0=0$.


Similarly, the $\chi^2$-divergence of $P$ with respect to $Q$ is defined as
\begin{equation}\label{eq:chi_square_def}
    \chi^2(P\|Q)=\sum_{s\in \supp(Q)}\frac{(P(s)-Q(s))^2}{Q(s)}.
\end{equation}
Both divergences are non-negative, and they vanish if and only
if $P = Q$. Moreover, the two divergences are related by the following well-known
inequality.
\begin{proposition}[\cite{f_div_sason}]\label{proposition:KL_Chi}
    Let $P$ and $Q$ be two probability distributions on a finite set $S$ such that $\supp(P)\subseteq\supp(Q)$. Then, it holds that
    \begin{equation}
        D(P\|Q)\leq \log(1+\chi^2(P\|Q))\leq \frac{\chi^2(P\|Q)}{\ln 2}.
    \end{equation}
\end{proposition}

Given a probability distribution $P$ on $S$, we denote by $P \otimes P$ the
product distribution on $S \times S$, defined by
\begin{equation}\label{eq:product_distribution}
    (P \otimes P)(s,s') = P(s)\, P(s'), \qquad \forall (s,s') \in S \times S.
\end{equation}

\subsection{Information Bottleneck Notation}
Let $(X,Y)\sim P_{XY}$ be a pair of random variables taking values in $\cX\times \cY$. We assume that $P_X(x)>0$ for all $x\in \cX$. In the optimization problems defined in~\eqref{eq:IB_def} and~\eqref{eq:L_beta_def}, one seeks a compressed representation (or \textit{encoder}) $T$ of $X$ that is conditionally independent from $Y$ given $X$. This type of encoder is formalized as follows.
\begin{definition}\label{def:encoder}
    Let $\cT$ be a finite set. An \emph{encoder} of $X$ is a conditional
    distribution (or channel) $P_{T\mid X}$ from $\cX$ to $\cT$, i.e., a
    collection $\{P_{T\mid X}(\cdot \mid x)\}_{x \in \cX}$ of probability
    distributions on $\cT$. The encoder $P_{T\mid X}$ induces a random variable $T$ taking values
    in $\cT$ such that $(X,Y,T)$ has joint distribution
    \begin{equation}\label{eq:encoder_joint}
        P_{XYT}(x,y,t) = P_X(x)\, P_{Y\mid X}(y \mid x)\, P_{T\mid X}(t \mid x),
        \qquad \forall (x,y,t) \in \cX \times \cY \times \cT.
    \end{equation}
    In other words, $T$ and $Y$ are conditionally independent given $X$.
\end{definition}
To simplify the notation, in what follows we identify an encoder with the
random variable $T$ it induces, and refer to $T$ itself as the encoder
whenever the channel $P_{T\mid X}$ is clear from the context.

From Definition~\ref{def:encoder} one obtains the following immediate consequence.

\begin{proposition}
    Let $\cT$ be a finite set. For every encoder $P_{T\mid X}$ defining the random variable $T\sim P_T$, it holds that
    \begin{equation}\label{eq:first_direction_encoder}
        \E_{T}[P_{X\mid T}(x\mid T)]=\sum_{t\in \cT} P_T(t)P_{X\mid T}(x\mid t)=P_X(x),\quad\text{for all } x\in \cX.
    \end{equation}
    Conversely, let $P$ be a probability distribution on $\cT$ and let $\{Q_t\}_{t\in \cT}$ be a collection of probability distribution on $\cX$ such that
    \begin{equation}\label{eq:posterior_encoder}
        \sum_{t\in \cT} P(t)Q_t(x) = P_X(x),\quad\text{for any } x\in\cX.
    \end{equation}
    Then the channel $P_{T\mid X}$ defined as
    \begin{equation}\label{eq:encoder_from_mixture}
        P_{T\mid X}(t\mid x)=\frac{P(t)Q_t(x)}{P_X(x)}, \quad\forall x\in\cX\text{ and } t\in\cT,
    \end{equation}
    defines an encoder of $X$ whose induced random variable $T$ satisfies $P_T(t)=P(t)$ for any $t\in \cT$ and $P_{X\mid T}(\cdot\mid t)=Q_t$ for every $t\in supp(P)\subseteq\cT$.
\end{proposition}
\begin{proof}
    The identity~\eqref{eq:first_direction_encoder} follows from the law of total probability.

    For the converse, we have that $P_{T\mid X}(t\mid x)\geq 0$ for all $x$ and $t$, since the right-hand side of~\eqref{eq:encoder_from_mixture} is non-negative. Moreover, by~\eqref{eq:posterior_encoder}, we have that
    \begin{equation}
        \sum_{t \in \cT} P_{T\mid X}(t \mid x) =\sum_{t\in \cT}\frac{P(t)Q_t(x)}{P_X(x)}=\frac{P_X(x)}{P_X(x)}=1,
    \end{equation}
    for every $x \in \cX$. Hence, $P_{T\mid X}$ is a valid channel from $\cX$ to $\cT$, and since $T$ depends only on $X$, $T$ is conditionally independent of $Y$ given $X$. Consequently, $P_{T\mid X}$ is an encoder of $X$. Moreover, one can also see that for any $t\in \cT$
    \begin{equation}
        P_T(t)=\sum_{x\in \cX} P_X(x)P_{T\mid X}(t\mid x)=\sum_{x\in \cX}P_X(x)\frac{P(t)Q_t(x)}{P_X(x)}=P(t), 
    \end{equation}
    and that, for $t\in \supp(P)$ and $x\in \cX$, by the Bayes' rule, we have that
    \begin{equation}
        P_{X\mid T}(x\mid t)=\frac{P_X(x)P_{T\mid X}(t\mid x)}{P_T(t)}= \frac{P_X(x)P(t)Q_t(x)}{P_X(x)P(t)}=Q_t(x).
    \end{equation}
\end{proof}

\subsection{Decision Problems}\label{subsec:decision}
In this section, we state the decision versions of the optimization problems~\eqref{eq:IB_def} and~\eqref{eq:L_beta_def}, which we will use to prove the NP-hardness\footnote{We refer to \cite{GJ} for the basic about NP-hardness.}. Throughout, a probability distribution is called
\emph{rational} if all its probabilities are rational numbers.

\smallskip
\noindent
{\IBT}

\noindent
\textsc{Input}: A rational probability distribution $P_{XY}$ on a finite
alphabet $\cX \times \cY$, and non-negative rational numbers $R$ and
$\vartheta$. 

\noindent
\textsc{Question}: Does there exist an encoder $P_{T\mid X}$ of $X$ inducing a random variable $T$ on a finite alphabet $\cT$ such that 
\begin{equation}
    I(Y;T)\geq \vartheta\quad\text{and}\quad I(X;T)\leq R?
\end{equation}

We notice that \IBT{} is equivalent to asking whether $\IB(P_{XY},R)\geq \vartheta$, where $\IB(P_{XY},R)$ is defined in~\eqref{eq:IB_def}.

\smallskip
\noindent
\IBL

\noindent
\textsc{Input:} A rational probability distribution $P_{XY}$ on a finite
alphabet $\cX \times \cY$, and a non-negative rational number $\tau$.

\noindent
\textsc{Question:} Does there exist an encoder $P_{T\mid X}$ inducing a random variable $T$ on a finite alphabet $\cT$ such that 
\begin{equation}
    I(Y;T)-\frac{1}{2}I(X;T)\geq \tau?
\end{equation}

We notice that \IBL{} asks whether $L_{1/2}(P_{XY})\geq \tau$, where $L_{1/2}(P_{XY})$ is defined in~\eqref{eq:L_beta_def}.

We prove the NP-hardness of \textsc{IB-Threshold} and  \textsc{IB-Lagrangian} by a reduction from the well-known \clique~problem~\cite{Karp}.
We briefly recall the \clique~problem.

First of all, a graph $G$ is a pair $(V(G),E(G))$, where $V(G)$ is a finite set of vertices of the graph and $E(G)$ is a set of unordered pairs $\{u,v\}$ of distinct vertices $u,v\in V(G)$, called edges of $G$. All graphs considered in this paper are simple, i.e., they do not contain edges joining a vertex to itself, that is,  for $u\in V(G)$ we have that $\{u,u\}\notin E(G)$.

A \textit{clique} of $G$ is a subset $C\subseteq V(G)$ such that $\{u,v\}\in E(G)$ for all distinct vertices $u,v\in C$. The size of a clique $C$ is its cardinality $|C|$, and a clique of size $k$ is called a $k$-clique. The \textit{clique number} of a graph $G$, denoted $\omega(G)$, is the largest size of a clique of $G$, that is, 
\begin{equation}\label{eq:clique_number_def}
    \omega(G) = \max\{\, |C| : C \subseteq V(G) \text{ is a clique of } G \,\}.
\end{equation}
We now recall the \clique{} problem, which is NP-complete~\cite{Karp}.

\smallskip
\noindent
\clique

\noindent
\textsc{Input:} An undirected graph $G$ and a positive integer $k$.

\noindent
\textsc{Question:} Does $G$ contain a clique of size $k$, i.e., is $\omega(G) \ge k$?


\section{Main results}\label{sec:main}
In this section, we present the main results of the work. By a reduction from \clique{}, we prove that both \IBT{} and \IBL{} are NP-Hard. Moreover, we also
show that approximating the optimal values $\IB(P_{XY}, R)$ and
$L_{1/2}(P_{XY})$ within an additive error that is polynomial in $1/|\cX|$, where $|\cX|$ is size of the alphabet of $X$, is NP-hard.

These results are formalized in the following results.

\begin{theorem}\label{thm:IBL_hard}
    The \IBL{} problem is NP-hard. Moreover, unless $\text{P}=\text{NP}$, there is no polynomial time algorithm that, given an arbitrary rational joint distribution $P_{XY}$ of $(X,Y)$ on a finite alphabet $\cX\times \cY$, outputs a value $v$ such
    that
    \begin{equation}
        \big| v - L_{1/2}(P_{XY}) \big| \le \frac{1}{216\, |\cX|^{3/2}}.
    \end{equation}
\end{theorem}
An easy reduction from the $\beta=1/2$ case allows us to extend Theorem \ref{thm:IBL_hard}
to any $\beta\in (0,1)$ (see Proposition
\ref{prop:other_fixed_beta}).

\begin{theorem}\label{thm:IBT_hard}
    The \IBT{} is NP-hard. Moreover, unless $\mathrm{P} = \mathrm{NP}$, there is
    no polynomial-time algorithm that, given a rational joint distribution
    $P_{XY}$ on a finite alphabet $\cX \times \cY$ and a positive rational
    number $R$, outputs a value $v$ such that
    \begin{equation}
        \big| v - \IB(P_{XY}, R) \big| \le \frac{1}{576|X|^{3/2}}.
    \end{equation}
\end{theorem}

\subsection{Proof overview}
Both theorems are proved by a polynomial-time reduction from \clique{}. We
briefly describe the idea of the reduction for \IBL{}. Given an instance $(G,k)$ of
\clique{}, we construct a larger graph $\G$ by inserting for each edge $e$ of $G$ a clique $C_e$ of size $k-1$ containing only the edge $e$ from the edges of $G$. This construction ensures that the cliques
$C_e$ partition the edges of $\G$, and that no clique of size larger than
$k-1$ is created, apart from those already present in $G$.  We then construct a joint distribution $P_{XY}$ where $X$ is a uniformly random variable on the oriented edges of $\G$ and, given $X=x$, the random variable $Y$ is one of the two vertices of the edge $x$, chosen uniformly at random.

The key idea is the following. If $G$ has no $k$-clique, the largest
cliques of $\G$ have size $k-1$, and we show that $L_{1/2}(P_{XY})$ is achieved by a
simple deterministic encoder, which maps each oriented edge $x$ to the
added clique $C_e$ containing it. If, instead, $G$ has a $k$-clique $K$, we show that
there exists an encoder that, using the $k$-clique $K$ of $G$, strictly improves over the deterministic one,
and that the improvement is at least inverse-polynomial in $|\cX|$, yielding both the NP-hardness of \IBL{} and the hardness of approximating
$L_{1/2}(P_{XY})$. 

The proof for \IBT{} follows from the same
construction, by a suitable choice of the rate budget $R$.


The rest of this section is organized as follows. In
Section~\ref{subsec:Aux_results}, we present some auxiliary results. Specifically, we
express the objective of the Lagrangian in terms of the posterior
distributions of an encoder, we introduce the distributions defined on a
graph, and we prove a lower bound on their cost. In Section~\ref{sec:reduction}, we describe
the construction of the graph $\G$ and of the joint distribution
$P_{XY}$, and we introduce the simple deterministic encoder $T_0$. In
Sections~\ref{subsec:no_instances} and~\ref{subsec:yes_instances}, we
show that $T_0$ is optimal if $G$ has no $k$-clique, and that it can be
strictly improved if  $G$ contains a $k$-clique. Finally, in
Sections~\ref{subsec:proof_IBL} and~\ref{subsec:proof_IBT}, we combine
the previous results, providing the proofs of Theorems~\ref{thm:IBL_hard}
and~\ref{thm:IBT_hard}.


