\end{equation}
and
\begin{equation}\label{eq:g_P_x_given_t}
    g_W(P_{X\mid T}(\cdot\mid t))=H(P_{Y\mid T}(\cdot\mid t))-\frac{1}{2}H(P_{X\mid T}(\cdot\mid t)).
\end{equation}

Using~\eqref{eq:gP_x} and~\eqref{eq:g_P_x_given_t} we obtain the following result.
}
The following lemma shows that the objective of the Lagrangian $L_{1/2}(P_{XY})$ depends on
an encoder only through the costs of its posterior distributions
$\{P_{X\mid T}(\cdot \mid t)\}_{t \in \cT}$.


\begin{lemma}\label{lemma:Lagrangian_expressed_wt_posteriors}
    Let $P_{T\mid X}$ be an encoder of $X$ inducing a random variable $T\sim P_T$ on $\cT$ with $P_T(t)>0$ for all $t\in \cT$, and let $W$ be the channel defined in~\eqref{eq:W_def}. Then, we have that
    \begin{equation}\label{eq:lagrangian_cost}
        I(Y;T)-\frac{1}{2}I(X;T)=g_{W}(P_X)-\E_{T}[g_W(P_{X\mid T}(\cdot\mid T))].
    \end{equation}
    In particular,
    \begin{equation}\label{eq:L_1/2_g_def}
        L_{1/2}(P_{XY})=g_W(P_X)-\inf_{P_{T\mid X: T-X-Y}}\E_{T}[g_W(P_{X\mid T}(\cdot\mid T))].
    \end{equation}
\end{lemma}
\begin{proof}
    By definition of mutual information in~\eqref{eq:mutual_information_def} and of conditional entropy in~\eqref{eq:conditional_entropy}, we have that
    \begin{equation}\label{eq:IXT_post}
        I(X;T) = H(X) - H(X \mid T)
        = H(P_X) - \E_{T}\Big[H\big(P_{X\mid T}(\cdot \mid T)\big)\Big],
    \end{equation}
    and similarly that
     \begin{equation}\label{eq:ITY_post}
        I(T;Y) = H(Y) - H(Y \mid T)
        = H(P_Y) - \E_{T}\Big[H\big(P_{Y\mid T}(\cdot \mid T)\big)\Big].
    \end{equation}
    Since $P_Y = W P_X$ and, by Lemma~\ref{lemma:posterior_Y_give_T},
    $P_{Y\mid T}(\cdot \mid t) = W P_{X\mid T}(\cdot \mid t)$ for every
    $t \in \cT$, subtracting one half of~\eqref{eq:IXT_post}
    from~\eqref{eq:ITY_post} gives
    \begin{align*}
        I(T;Y) - \frac12 I(X;T)
        &= H(W P_X) - \frac12 H(P_X)
        - \E_{T}\Big[H\big(W P_{X\mid T}(\cdot \mid T)\big)
        - \frac12 H\big(P_{X\mid T}(\cdot \mid T)\big)\Big] \\
        &= g_W(P_X) - \E_{T}\Big[g_W\big(P_{X\mid T}(\cdot \mid T)\big)\Big],
    \end{align*}
    which proves~\eqref{eq:lagrangian_cost}. 

    Finally, by~\eqref{eq:L_beta_def} and~\eqref{eq:lagrangian_cost}, we obtain that
    \begin{align}
         L_{1/2}(P_{XY})&=\sup_{P_{T\mid X}:T-X-Y} [I(Y;T)-\frac{1}{2} I(X;T)]\nonumber\\
         &=\sup_{P_{T\mid X}:T-X-Y} \Bigg[ g_W(P_X) - \E_{T}\Big[g_W\big(P_{X\mid T}(\cdot \mid T)\big)\Big]\Bigg]\nonumber\\
         &=g_W(P_X)-\inf_{P_{T\mid X: T-X-Y}}\E_{T}[g_W(P_{X\mid T}(\cdot\mid T))],
    \end{align}
    where the last equality holds because $g_W(P_X)$ does not depend on $T$.
\end{proof}
Lemma~\ref{lemma:Lagrangian_expressed_wt_posteriors} provides a natural
strategy to lower and upper bound $L_{1/2}(P_{XY})$. Indeed, if
$g_W(P) \ge c$ for every probability distribution $P$ on $\cX$, then, since
each posterior $P_{X\mid T}(\cdot \mid t)$ is a probability distribution on
$\cX$, the infimum in~\eqref{eq:L_1/2_g_def} is at least $c$, and hence
\begin{equation}\label{eq:L_upper_strategy}
    L_{1/2}(P_{XY}) \le g_W(P_X) - c.
\end{equation}
On the other hand, for every fixed encoder $T$ of $X$, ~\eqref{eq:L_1/2_g_def} yields the following lower bound:
\begin{equation}\label{eq:L_lower_strategy}
    L_{1/2}(P_{XY}) \ge g_W(P_X)
    - \E_{T}\Big[g_W\big(P_{X\mid T}(\cdot \mid T)\big)\Big].
\end{equation}

\smallskip
We now focus on the specific pair of random variables $(X,Y)\sim P_{XY}$ that we build from an arbitrary graph $G$. Let $G$ be a graph
with at least one edge, and let
\begin{equation}\label{eq:oriented_edges}
    A(G) = \big\{(u,v) \in V(G) \times V(G) : \{u,v\} \in E(G)\big\}
\end{equation}
denote the set of $2|E(G)|$ oriented edges of $G$.

We let $X$ be uniformly distributed on $A(G)$, that is,
$P_X(x) = 1/|A(G)|$ for every $x \in A(G)$, and, given $X = x$, we let $Y$
be one of the two vertices of the edge $x$, chosen uniformly at random.
Then $(X,Y)$ takes values in $A(G) \times V(G)$, and the channel $W_G$ from
$A(G)$ to $V(G)$ corresponding to the conditional distribution
$P_{Y\mid X}$ is given by
\begin{equation}\label{eq:endpoint_channel}
    W_G\big(w \mid (u,v)\big) =
    \begin{cases}
        1/2, & w \in \{u,v\},\\
        0, & \text{otherwise},
    \end{cases}
\end{equation}
for every $(u,v) \in A(G)$ and $w \in V(G)$.

We also write $g_G=g_{W_G}$ for the cost function~\eqref{eq:g_def} associated
with the channel $W_G$, that is,
\begin{equation}\label{eq:g_W_G_def}
    g_G(P)=H(W_GP)-\frac{1}{2}H(P),
\end{equation}
for every probability distribution $P$ on $A(G)$.


We now observe some useful properties of $g_G$. We first compute the cost 
of the uniform distribution on the oriented edges of a clique of $G$. For every
integer $j \ge 2$, let
\begin{equation}\label{eq:c_j_def}
    c_j = -\frac12 \log \left(1-\frac{1}{j}\right).
\end{equation} 
We notice that $c_j$ is strictly decreasing in $j$. For a clique $C$ of $G$
of size $j \ge 2$, let
\begin{equation}
    A(C) = \{(u,v) \in C \times C : u \neq v\} \subseteq A(G)
\end{equation}
be the set of its $j(j-1)$ oriented edges, and let $U_C$ denote the probability distribution on $A(G)$ that is uniform on $A(C)\subseteq A(G)$, namely,
\begin{equation}\label{eq:U_C_def}
    U_C(x) =
    \begin{cases}
        \dfrac{1}{j(j-1)}, & x \in A(C),\\[4pt]
        0, & \text{otherwise}.
    \end{cases}
\end{equation}

\begin{lemma}\label{lemma:cost_clique}
    Let $C$ be a clique of $G$ of size $j \ge 2$. Then $W_G U_C$ is the
    uniform distribution on $C$, that is,
    \begin{equation}\label{eq:W_U_C}
        (W_GU_C)(v)=\begin{cases}
            1/j &\text{if } v\in C,\\
            0&\text{if } v\in V(G)\setminus C.
        \end{cases}
    \end{equation}
    and
    \begin{equation}\label{eq:cost_clique}
        g_G(U_C) = c_j.
    \end{equation}
\end{lemma}
\begin{proof}
   For every $v \in V(G)$, by~\eqref{eq:U_C_def},
    \begin{equation}
        (W_G U_C)(v) = \sum_{(w,u) \in A(G)} W_G\big(v \mid (w,u)\big)\, U_C(w,u)
        = \frac{1}{j(j-1)} \sum_{(w,u) \in A(C)} W_G\big(v \mid (w,u)\big).
    \end{equation}
    By~\eqref{eq:endpoint_channel}, $W_G(v \mid (w,u)) = 1/2$ if
    $v \in \{w,u\}$, and $0$ otherwise. If $v \in C$, exactly $2(j-1)$
    oriented edges of $A(C)$ have $v$ as an endpoint, hence
    \begin{equation}
        (W_G U_C)(v) = \frac{1}{j(j-1)} \cdot 2(j-1) \cdot \frac12 = \frac1j.
    \end{equation}
    If $v \notin C$, no oriented edge of $A(C)$ has $v$ as an endpoint, hence
    $(W_G U_C)(v) = 0$. This proves~\eqref{eq:W_U_C}. Moreover, since
    $H(W_G U_C) = \log j$ and $H(U_C) = \log\big(j(j-1)\big)$, from~\eqref{eq:g_W_G_def} we finally get that
    \begin{equation*}
        g_G(U_C) = \log j - \frac12 \log\big(j(j-1)\big)
        = -\frac12 \log\Big(1 - \frac1j\Big) = c_j,
    \end{equation*}
    which concludes the proof.
\end{proof}

Now, Lemma~\ref{lemma:entropic_turan} shows that no distribution $P$ on $A(G)$ has a cost $g_G(P)$ smaller than $c_{\omega(G)}$. Before showing it, we recall the following result from~\cite{MS}.

\begin{lemma}[\cite{MS}]\label{lemma:motzkin_straus}
    For every probability distribution $P$ on $V(G)$,
    \begin{equation}\label{eq:motzkin_straus}
        \sum_{(u,v) \in A(G)} P(u)\, P(v) \le 1 - \frac{1}{\omega(G)}.
    \end{equation}
\end{lemma}

\begin{lemma}\label{lemma:entropic_turan}
    Let $g_G$ be the function defined in~\eqref{eq:g_W_G_def}. Then, for every probability distribution $P$ on $A(G)$, it holds that
    \begin{equation}\label{eq:entropic_turan}
        g_G(P) \ge c_{\omega(G)},
    \end{equation}
    with equality if $P = U_C$ for a clique $C$ of size $\omega(G)$.
\end{lemma}
\begin{proof}
    Let $\pi = W_G P$, and let $P_1$ and $P_2$ denote the
    distributions on $V(G)$ such that for any $v \in V(G)$
    \begin{equation}
        P_1(v)=\sum_{u: (v,u)\in A(G)} P(v,u)\quad\text{and}\quad P_2(v)=\sum_{u: (u,v)\in A(G)}P(u,v).
    \end{equation}
    By~\eqref{eq:endpoint_channel}, $W_G(v\mid (w,u))=1/2$ if and only if $v\in\{w,u\}$. Hence, we have that
    \begin{align}
        \pi(v)&=\sum_{(w,u)\in A(G)}W_G(v\mid (w, u))P(w,u)\nonumber\\
        &=\frac{1}{2}\sum_{u:(v,u)\in A(G)}P(v,u)+\frac{1}{2}\sum_{w:(w,v)\in A(G)}P(w,v)\nonumber\\
        &=\frac{1}{2}\left(P_1(v)+P_2(v)\right).\label{eq:pi_P_1_P_2}
    \end{align}
    Let us now extend $P$ to a distribution on all $V(G) \times V(G)$ by setting it to
    zero outside $A(G)$.  We observe that if
    $P(u,v) > 0$, then $\pi(u) \ge \frac12 P_1(u) > 0$ and
    $\pi(v) \ge \frac12 P_2(v) > 0$. Hence
    $\supp(P) \subseteq \supp(\pi \otimes \pi)$, and $D(P\|\pi\otimes\pi)$ is finite. Moreover, using~\eqref{eq:pi_P_1_P_2}, we obtain that
    \begin{align}
        D(P\|\pi\otimes\pi)&=-H(P)-\sum_{(u,v)\in V(G)\times V(G)} P(u,v)\log (\pi(v)\pi(u))\nonumber\\
        &=-H(P)-\sum_{(u,v)\in A(G)} P(u,v)\log (\pi(u)\pi(v))\\
        &=-H(P)-\sum_{v:(u,v)\in A(G)} P(u,v)\log\pi(u)-\sum_{u:(u,v)\in A(G)} P(u,v)\log\pi(v)\\
        &=-H(P)-\sum_{u\in V(G)} P_1(u)\log \pi(u)-\sum_{v\in V(G)} P_2(v)\log \pi(v)\\
        &=-H(P)-\sum_{v\in V(G)} (P_1(v)+P_2(v))\log \pi(v)\\
        &=-H(P)-2\sum_{v\in V(G)} \pi(v)\log \pi(v)\\
        &=2H(\pi)-H(P)=2g_G(P),\label{eq:equality_KL_g_G}
    \end{align}
    where the last equality follows from $\pi= W_G P$ and~\eqref{eq:g_W_G_def}.

    Now, by applying Jensen's inequality on the concavity of the logarithm we obtain the following lower bound on $D(P\|\pi\otimes\pi)$:
    \begin{equation}
        D(P\|\pi\otimes\pi)\geq -\log\left(\sum_{(v,u)\in A(G)} \pi(v)\pi(u)\right).\label{eq:lower_bound_KL}
    \end{equation}
    By Lemma~\ref{lemma:motzkin_straus}, \eqref{eq:lower_bound_KL} yields
    \begin{equation}
        D(P\|\pi\otimes\pi)\geq-\log\left(1-\frac{1}{\omega(G)}\right)=2c_{\omega(G)}.\label{eq:bound_KL_2}
    \end{equation}
    Combining~\eqref{eq:equality_KL_g_G} and~\eqref{eq:bound_KL_2} yields~\eqref{eq:entropic_turan}. The equality for $P = U_C$ instead follows from Lemma~\ref{lemma:cost_clique}, since for a clique $C$ of size $\omega(G)$ we have that $g_G(U_C)=c_{\omega(G)}$.
\end{proof}
The bound of Lemma~\ref{lemma:entropic_turan} can be seen as an entropic form of Tur\'an's theorem.  For symmetric distributions, that is, when
$P(u,v) = P(v,u)$ for all $(u,v) \in A(G)$, it was obtained by Chao and
Yu~\cite{CY}.


Finally, we bound the decrease of the cost when the size of a clique
increases by one.

\begin{lemma}\label{lemma:clique_gap}
    For every integer $m \ge 2$,
    \begin{equation}\label{eq:clique_gap}
        c_m - c_{m+1} \ge \frac{1}{2m^2 \ln 2}.
    \end{equation}
\end{lemma}

\begin{proof}
    By~\eqref{eq:c_j_def},
    \begin{equation}
        c_m - c_{m+1}
        = \frac12 \log\Big(\frac{m}{m-1} \cdot \frac{m}{m+1}\Big)
        = -\frac12 \log\Big(1 - \frac{1}{m^2}\Big)
        \ge \frac{1}{2m^2 \ln 2},
    \end{equation}
    where the inequality follows from $-\ln(1-x) \ge x$ for $0 \le x < 1$.
\end{proof}

\subsection{The reduction}\label{sec:reduction}
We now describe the reduction from \clique{}. Let $(G,k)$ be an instance of \clique{}. Throughout the section, let
\begin{equation}\label{eq:some_notations}
    n=|V(G)|,\quad N=|E(G)|,\quad B=\binom{k}{2}=\frac{k(k-1)}{2}.
\end{equation}
For the sake of simplicity, we restrict to instances of \clique{} satisfying 
\begin{equation}\label{eq:assumption_on_G}
    k\geq 4\quad\text{and}\quad N\geq B.
\end{equation}
This does not affect the NP-hardness.
Indeed, if $k\leq 3$ the \clique{} problem can be solved in $O(n^3)$ time by examining all subsets of at most three vertices. On the other hand, if $N<B$, then the instance is trivial because there does not exist a $k$-clique $C$ in $G$ since $C$ should have $B>N$ edges.

Now, let $m = k-1 \ge 3$. We construct an extended graph $\G$ from $G$ as follows: for
each edge $e=\{u,v\} \in E(G)$, we add a set $S_e$ of $m-2$ new vertices, and we
add all the edges needed to make $C_e = \{u,v\} \cup S_e$ a clique of size $m$. No other vertices or edges are added.

We observe the following properties of the new constructed graph $\G$.

\begin{lemma}\label{lemma:gadget}
      The graph $\G$ satisfies the following properties:
      \begin{enumerate}
          \item Let $E(C_e)$ denote the edges of the clique $C_e$ for any $e\in E(G)$. The collection $\{E(C_e)\}_{e\in E(G)}$ is a partition of $E(\G)$, that is,
          \begin{equation}
              \bigcup_{e\in E(G)} E(C_e)=E(\G)
          \end{equation}
          and
          \begin{equation}
              E(C_e)\cap E(C_{e'})=\emptyset, \quad\forall e,e'\in E(G) \text{ with }e\neq e'.
          \end{equation}

          \item The number of oriented edges of $\G$ is
          \begin{equation}
              M=|A(\G)|=Nm(m-1).
          \end{equation}

          \item $\omega(\G)=\max\{\omega(G),m\}$.
      \end{enumerate}
\end{lemma}
\begin{proof}
    1. By construction of $\G$, every edge of $\G$ belongs to $E(C_e)$ for some $e\in E(G)$. Thus, it suffices to show that for each edge $x\in E(\G)$ there exists a unique $e\in E(G)$ such that $x\in E(C_e)$.

    Let $x=\{u,v\}$ be an edge of $\G$. Assume first that $x\in E(G)$. Since for every $e\in E(G)$ $C_e\cap V(G)=e$, we have that $E(C_e)\cap E(G)=\{e\}$ for any $e\in E(G)$. Hence, it follows that $x\in E(C_e)$ if and only if $x=e$.


    If $x=\{u,v\}\notin E(G)$, then $x$ is an edge added in the construction of $\G$, and at least one vertex between $u$ and $v$, say $u$, belongs to $S_e$ for some $e \in E(G)$. Moreover, $x\in E(C_e)$. Since the sets $S_e$ are
    pairwise disjoint, it follows that $u \notin C_{e'}$ for every $e' \neq e$. Hence, for every $e'\neq e$, we have that
    $x \notin E(C_{e'})$. Consequently, there exists a unique $e\in E(G)$ such that $x\in E(C_e)$.

    Therefore, each edge of $\G$ lies in exactly one of the sets
    $E(C_e)$, with $e \in E(G)$. Hence,  $\{E(C_e)\}_{e\in E(G)}$ forms a partition of $E(\G)$.

    \smallskip
    2. By construction of $\G$, for each edge $e\in E(G)$, we add a clique of size $m$. Therefore, the total number of oriented edges is
    \begin{equation}
        |A(\G)|=2|E(G)|\frac{m(m-1)}{2} = Nm(m-1).
    \end{equation}

    \smallskip
    3. We first show that $\omega(\G) \le \max\{\omega(G), m\}$. 

    Let $K$ be
    a clique of $\G$.
    If $K$ contains a vertex $z \in S_e$ for some $e \in E(G)$, then, by
    construction of $\G$, all the neighbours of $z$, that are the vertices adjacent to $z$, belong to $C_e$. Therefore, it follows that
    $K \subseteq C_e$, and hence $|K| \le |C_e| = m$.

    If $K$ does not contain a vertex $z\in S_e$ for any $e\in E(G)$, then we have that $K \subseteq V(G)$. Therefore, $K$ is
    a clique of $G$, and $|K| \le \omega(G)$.

    Conversely,  $G$ is a subgraph of $\G$, so every clique of $G$ is a
    clique of $\G$, and $\omega(\G) \ge \omega(G)$. Moreover, each $C_e$ is
    a clique of $\G$ of size $m$, and $E(G) \neq \emptyset$
    by assumption. Thus, $\omega(\G) \ge m$. Putting all together we have that    $\omega(\G) = \max\{\omega(G), m\}$.
\end{proof}

Having established the properties of $\G$, we now define the joint
distribution $P_{XY}$ of $(X,Y)$ on $\G$ as described in
Section~\ref{subsec:Aux_results}.
Thus, $X$ is uniformly distributed on $A(\G)$, that is, 
\begin{equation}\label{eq:P_X_uniform}
    P_X(u,v) = \frac{1}{M}, \qquad \forall (u,v) \in A(\G),
\end{equation}
and, given $X=(u,v)$, $Y$ is one of the two vertices of the edge $(u,v)$, chosen uniformly at random. 
 Hence $\cX = A(\G)$, $\cY = V(\G)$, and the channel $W_{\G}$
from $\cX$ to $\cY$ is defined as in~\eqref{eq:endpoint_channel}, that is,
\begin{equation}\label{eq:endpoint_channel_G_bar}
    W_{\G}\big(w \mid (u,v)\big) =
    \begin{cases}
        1/2, & w \in \{u,v\},\\
        0, & \text{otherwise},
    \end{cases}
\end{equation}
for every $(u,v) \in A(\G)$ and $w \in V(\G)$. Moreover, we denote by $g_{\G} = g_{W_{\G}}$ the corresponding cost,
defined as in~\eqref{eq:g_W_G_def} with $G$ replaced by $\G$.

Recalling that $|A(\G)| = M$, the joint distribution $P_{XY}$ of $(X,Y)$ is therefore
\begin{equation}\label{eq:P_XY_explicit}
    P_{XY}\big((u,v), w\big) = P_X(u,v)\, W_{\G}\big(w \mid (u,v)\big) =
    \begin{cases}
        \dfrac{1}{2M}, & w \in \{u,v\},\\[4pt]
        0, & \text{otherwise},
    \end{cases}
\end{equation}
for every $(u,v) \in A(\G)$ and $w \in V(\G)$.
Now, by property~1 of
Lemma~\ref{lemma:gadget}, and since $(u,v) \in A(C_e)$ if and only if
$\{u,v\} \in E(C_e)$, every oriented edge $(u,v) \in A(\G)$ belongs to
$A(C_e)$ for exactly one $e \in E(G)$. Thus, we can define the
following deterministic encoder $T_0$, taking values in $E(G)$:
\begin{equation}\label{eq:T_0_def}
    P_{T_0 \mid X}(e \mid x) =
    \begin{cases}
        1, & \text{if }x \in A(C_e),\\
        0, & \text{otherwise},
    \end{cases}
    \qquad \forall x \in A(\G),\ e \in E(G).
\end{equation}
In other words, $T_0$ maps each oriented edge $(u,v)$ to the unique edge
$e \in E(G)$ such that $(u,v) \in A(C_e)$, that is, it reveals the clique
$C_e$ containing $(u,v)$. Moreover, since $T_0$ is a deterministic
function of $X$, the random variables $T_0$ and $Y$ are conditionally
independent given $X$. In addition, the encoder $T_0$ satisfies the following
properties.
\begin{lemma}\label{lemma:T_0}
    The encoder $T_0$ defined in~\eqref{eq:T_0_def} satisfies
    \begin{equation}\label{eq:T_0_distribution}
        P_{T_0}(e) = \frac1N
        \qquad \text{and} \qquad
        P_{X \mid T_0}(\cdot \mid e) = U_{C_e},
        \qquad \forall e \in E(G).
    \end{equation}
    Moreover,
    \begin{equation}\label{eq:Lambda_0_def}
        I(Y;T_0) - \frac12 I(X;T_0) = g_{\G}(P_X) - c_m = \Lambda_0.
    \end{equation}
    In particular, $L_{1/2}(P_{XY}) \ge \Lambda_0$.
\end{lemma}
\begin{proof}
    We first prove~\eqref{eq:T_0_distribution}.
    For every $e \in E(G)$, the set $A(C_e)$ contains $m(m-1)$ oriented
    edges, each of probability $1/M$ under $P_X$. Hence, by~\eqref{eq:T_0_def} we have that
    \begin{align}
        P_{T_0}(e) &= \sum_{x \in A(\G)} P_X(x)\, P_{T_0 \mid X}(e \mid x)\nonumber\\
        &=\frac{1}{M}\sum_{x \in A(\G)} P_{T_0 \mid X}(e \mid x)\nonumber\\
        &= \frac{|A(C_e)|}{M}=\frac{m(m-1)}{M} = \frac1N,\nonumber
    \end{align}
    where the last equality follows by recalling that $M=m(m-1)N$.

    Moreover, by the Bayes' rule, for every $x \in A(\G)$, we have that
    \begin{equation}
        P_{X \mid T_0}(x \mid e)
        = \frac{P_X(x)\, P_{T_0 \mid X}(e \mid x)}{P_{T_0}(e)}
        =
        \begin{cases}
            \dfrac{N}{M} = \dfrac{1}{m(m-1)}, & x \in A(C_e),\\[4pt]
            0, & \text{otherwise},
        \end{cases}
    \end{equation}
    that is, $P_{X \mid T_0}(\cdot \mid e) = U_{C_e}$, where $U_{C_e}$ is the probability distribution on $A(\G)$ that is uniform on $A(C_e)$ (cfr.~\eqref{eq:U_C_def}).
    This proves~\eqref{eq:T_0_distribution}.

    Now, we prove~\eqref{eq:Lambda_0_def}. By Lemma~\ref{lemma:Lagrangian_expressed_wt_posteriors}
    and~\eqref{eq:T_0_distribution}, it follows that
    \begin{equation}\label{eq:recall_cost_T_0}
        I(Y;T_0) - \frac12 I(X;T_0)
        = g_{\G}(P_X) - \frac1N \sum_{e \in E(G)} g_{\G}(U_{C_e}).
    \end{equation}
    Since each $C_e$ is a clique of $\G$ of size $m$,
    Lemma~\ref{lemma:cost_clique} gives that $g_{\G}(U_{C_e}) = c_m$ for every
    $e \in E(G)$. This together with~\eqref{eq:recall_cost_T_0} proves~\eqref{eq:Lambda_0_def}. Finally,
    $L_{1/2}(P_{XY}) \ge \Lambda_0$ immediately follows from the definition of
    $L_{1/2}(P_{XY})$ in~\eqref{eq:L_beta_def} as a supremum over all encoders.
\end{proof}

We now show that, if $G$ has no $k$-clique, then the deterministic encoder $T_0$ defined in~\eqref{eq:T_0_def} is optimal, that is, $L_{1/2}(P_{XY}) = \Lambda_0$. On the other hand, if $G$ contains a
$k$-clique, there exists an encoder that  improves on $T_0$ by
at least a quantity $\delta > 0$, that is, $L_{1/2}(P_{XY}) > \Lambda_0+\delta$.

\subsubsection{No-instances: $G$ does not contain a $k$-clique}\label{subsec:no_instances}
We demonstrate that, if $G$ has no $k$-clique, then no encoder of $X$ improves on
$T_0$.

\begin{lemma}\label{lemma:no_instance}
    Let $P_{XY}$ be the joint distribution defined in~\eqref{eq:P_XY_explicit}, and assume that $\omega(G) < k$. Then every encoder $T$ of $X$ satisfies
    \begin{equation}\label{eq:no_instance}
        I(Y;T) - \frac12 I(X;T) \le \Lambda_0.
    \end{equation}
    Consequently, $L_{1/2}(P_{XY}) = \Lambda_0$ and
    \begin{equation}\label{eq:no_instance_IB}
        \IB(P_{XY}, R) \le \frac{R}{2} + \Lambda_0, \qquad \forall R \ge 0.
    \end{equation}
\end{lemma}

\begin{proof}
    Since $\omega(G) \le k-1 = m$, property~3 of Lemma~\ref{lemma:gadget}
    gives $\omega(\G) = m$. Hence, by Lemma~\ref{lemma:entropic_turan}
    applied to the graph $\G$, we have $g_{\G}(Q) \ge c_m$ for every
    probability distribution $Q$ on $A(\G)$. In particular, this holds for
    every posterior distribution $P_{X\mid T}(\cdot \mid t)$ of an encoder
    $T$ of $X$. Thus, by Lemma~\ref{lemma:Lagrangian_expressed_wt_posteriors}, for every encoder $T$ of $X$ we obtain that
    \begin{equation*}
        I(Y;T) - \frac12 I(X;T)
        = g_{\G}(P_X) - \E_T\Big[g_{\G}\big(P_{X\mid T}(\cdot \mid T)\big)\Big]
        \le g_{\G}(P_X) - c_m = \Lambda_0,
    \end{equation*}
    which proves~\eqref{eq:no_instance}. Taking the supremum over all
    encoders gives $L_{1/2}(P_{XY}) \le \Lambda_0$, and by Lemma~\ref{lemma:T_0} we have that $L_{1/2}(P_{XY})\geq \Lambda_0$. Hence, $L_{1/2}(P_{XY}) = \Lambda_0$.

    Now, if $T$ is an encoder with $I(X;T) \le R$,
    then~\eqref{eq:no_instance} gives
    \begin{equation*}
        I(Y;T) \le \frac12 I(X;T) + \Lambda_0 \le \frac{R}{2} + \Lambda_0.
    \end{equation*}
    Taking the supremum over all such encoders yields~\eqref{eq:no_instance_IB}.
\end{proof}


\subsubsection{Yes-instances: $G$ does contain a $k$-clique}\label{subsec:yes_instances}
We now assume that $G$ contains a $k$-clique $K$, and we show that, using $K$, the encoder $T_0$ can be strictly improved.
Let
\begin{equation}\label{eq:p_def}
    p = \frac{1}{12 m^2},
\end{equation}
and let $T_1$ be the encoder taking values in $\{\star\} \cup E(G)$, where
$\star$ is a new symbol, defined by
\begin{equation}\label{eq:T_1_def}
    P_{T_1 \mid X}(\star \mid x) =
    \begin{cases}
        p, & \text{if } x \in A(K),\\
        0, & \text{otherwise},
    \end{cases}

